  readinessSnapshotOf(
    parseGhJson<{
      statusCheckRollup?: unknown;
      reviewDecision?: unknown;
      isDraft?: unknown;
      state?: unknown;
      mergeable?: unknown;
      mergeStateStatus?: unknown;
    }>(
      await runGh(
        [
          'pr',
          'view',
          String(number),
          '--json',
          'statusCheckRollup,reviewDecision,isDraft,state,mergeable,mergeStateStatus',
        ],
        repoRoot,
        timeoutMs,
      ),
      'gh pr view',
    ),
  ),
